public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Sets the result of a shipping query; for bots only
    /// </summary>
    public Task<TdLib.TdApi.Objects.Ok> AnswerShippingQueryAsync(long shippingQueryId = default, ShippingOption[] shippingOptions = default, string errorMessage = default)
    {

           using var activity =  StartCallActivity("AnswerShippingQueryAsync", typeof(AnswerShippingQuery).FullName ?? "AnswerShippingQueryAsync");

           try
           {
             return client.AnswerShippingQueryAsync(shippingQueryId, shippingOptions, errorMessage);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
